  "latest_plan": "Agent 4 will take ISSUE-0002::review and Agent 5 will take ISSUE-0001::triage (confirmed on private coalition board and public board; ready to execute).",
  "acknowledgment": {
    "status": "supported",
    "evidence_ids": [
      "event_0",
